// Utility functions for the frontend

// Format date to readable format
export const formatDate = (date) => {
  if (!date) return '';
  return new Date(date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

// Format time
export const formatTime = (time) => {
  if (!time) return '';
  return new Date(time).toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit'
  });
};

// Validate email
export const isValidEmail = (email) => {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email);
};

// Validate phone - exactly 10 digits
export const isValidPhone = (phone) => {
  const re = /^[0-9]{10}$/;
  return re.test(phone);
};

// Validate name - minimum 2 characters, letters and spaces only
export const isValidName = (name) => {
  if (!name || name.trim().length < 2) return false;
  const re = /^[a-zA-Z\s]{2,}$/;
  return re.test(name.trim());
};

// Validate password - minimum 6 characters
export const isValidPassword = (password) => {
  return password && password.length >= 6;
};

// Validate password strength - optional: includes uppercase, lowercase, numbers
export const isValidPasswordStrength = (password) => {
  if (!password || password.length < 6) return false;
  const hasUppercase = /[A-Z]/.test(password);
  const hasLowercase = /[a-z]/.test(password);
  const hasNumber = /[0-9]/.test(password);
  return hasUppercase && hasLowercase && hasNumber;
};

// Check if passwords match
export const isPasswordsMatch = (password, confirmPassword) => {
  return password === confirmPassword && password.length > 0;
};

// Validate date is not in the past
export const isValidDate = (dateString) => {
  if (!dateString) return false;
  const selectedDate = new Date(dateString);
  const now = new Date();
  return selectedDate > now;
};

// Validate date range (start before end)
export const isValidDateRange = (startDate, endDate) => {
  if (!startDate || !endDate) return false;
  const start = new Date(startDate);
  const end = new Date(endDate);
  return start < end;
};

// Validate positive number
export const isValidPositiveNumber = (num) => {
  const number = parseFloat(num);
  return !isNaN(number) && number > 0;
};

// Validate text field - minimum characters
export const isValidText = (text, minLength = 3) => {
  return text && text.trim().length >= minLength;
};

// Get all validation error messages
export const getValidationErrors = (formData, requiredFields = []) => {
  const errors = {};
  
  requiredFields.forEach(field => {
    const value = formData[field.name];
    
    switch(field.type) {
      case 'email':
        if (!value) {
          errors[field.name] = `${field.label} is required`;
        } else if (!isValidEmail(value)) {
          errors[field.name] = 'Please enter a valid email address';
        }
        break;
      case 'phone':
        if (!value) {
          errors[field.name] = `${field.label} is required`;
        } else if (!isValidPhone(value)) {
          errors[field.name] = 'Phone number must be exactly 10 digits';
        }
        break;
      case 'name':
        if (!value) {
          errors[field.name] = `${field.label} is required`;
        } else if (!isValidName(value)) {
          errors[field.name] = 'Name must be at least 2 characters and contain only letters';
        }
        break;
      case 'password':
        if (!value) {
          errors[field.name] = `${field.label} is required`;
        } else if (!isValidPassword(value)) {
          errors[field.name] = 'Password must be at least 6 characters';
        }
        break;
      case 'text':
        if (!value) {
          errors[field.name] = `${field.label} is required`;
        } else if (!isValidText(value, field.minLength || 3)) {
          errors[field.name] = `${field.label} must be at least ${field.minLength || 3} characters`;
        }
        break;
      case 'number':
        if (!value) {
          errors[field.name] = `${field.label} is required`;
        } else if (!isValidPositiveNumber(value)) {
          errors[field.name] = `${field.label} must be a positive number`;
        }
        break;
      default:
        if (!value) {
          errors[field.name] = `${field.label} is required`;
        }
    }
  });
  
  return errors;
};

// Get event status color
export const getStatusColor = (status) => {
  switch(status) {
    case 'pending': return '#ffc107';
    case 'approved': return '#28a745';
    case 'rejected': return '#dc3545';
    case 'completed': return '#17a2b8';
    default: return '#6c757d';
  }
};

// Truncate text
export const truncateText = (text, maxLength = 100) => {
  if (text.length <= maxLength) return text;
  return text.substring(0, maxLength) + '...';
};

export default {
  formatDate,
  formatTime,
  isValidEmail,
  isValidPhone,
  getStatusColor,
  truncateText,
};
